INSERT INTO public.quizzes (id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata)
SELECT id, title, subject, grade, questions, created_by, is_published, description, quiz_type, difficulty_level, time_limit_minutes, passing_score_percentage, total_questions, allow_retakes, show_answers_after_submission, tags, metadata FROM jsonb_populate_recordset(NULL::public.quizzes, $smartbridge$[{"id":"3a0b7817-435a-5f1a-a76d-18227e7fe115","title":"Business Studies · Grade 11 · Term 2: Marketing, production and ethical decisions · Set A","subject":"Business Studies","grade":"Grade 11","questions":[{"question":"A business asks experts for anonymous opinions over several rounds. Which technique is this?","options":["Random sampling only","Delphi technique","A cash budget","Direct selling"],"correct_index":1,"explanation":"Delphi collects expert judgments, shares summaries and repeats rounds. Anonymity can reduce the influence of dominant individuals.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which decision belongs to distribution policy?","options":["What colour the logo should be only","How much tax a worker owes","Whether to sell directly or through retailers","Which emergency exit to lock"],"correct_index":2,"explanation":"Distribution policy concerns how products reach customers. Channels can be direct or involve intermediaries.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"How does quality control differ from production planning?","options":["Quality control guarantees zero defects forever","Planning means never checking products","Both terms mean advertising only","It checks outputs against standards; planning arranges production activities"],"correct_index":3,"explanation":"Production planning sets resources, sequence and timing. Quality control checks whether products meet defined standards.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"A salesperson knows a product has a defect but hides it. What is the ethical response?","options":["Disclose relevant facts and follow the remedy process","Conceal the defect to secure the sale","Blame the customer before use","Alter the receipt to hide evidence"],"correct_index":0,"explanation":"Honest disclosure and appropriate remedies support trust and ethical conduct. Professional behaviour does not mean maximising sales at any cost.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A factory reduces inspection to cut costs, after which defects and returns rise. What should management evaluate?","options":["Only the saving on inspection wages.","Only the number of adverts published.","Total quality costs, including prevention, inspection, returns and lost customers.","Whether customers can be prevented from reporting defects."],"correct_index":2,"explanation":"An isolated cost reduction can increase total costs. Compare prevention and appraisal spending with internal and external failure costs, using evidence to choose a sustainable quality approach.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Marketing, production and ethical decisions. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","bst"],"metadata":{"term":2,"focus":"Marketing, production and ethical decisions","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"52136f58-0be2-5227-9d95-e8e20b3ac00d","title":"Business Studies · Grade 11 · Term 3: Action plans, presentations and team development · Set A","subject":"Business Studies","grade":"Grade 11","questions":[{"question":"What does a Gantt chart show in an action plan?","options":["Only the final profit figure","Only the owners' ages","Tasks and their timing along a timeline","A list of national laws"],"correct_index":2,"explanation":"A Gantt chart shows when tasks start and finish, helping track overlapping work and dependencies.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"An entrepreneur tests a small version of a product before expanding. What does this demonstrate?","options":["A guarantee that failure is impossible","Avoidance of all decisions","Proof that planning is unnecessary","Managed risk-taking using evidence"],"correct_index":3,"explanation":"Testing assumptions can reduce uncertainty and reveal improvements. Entrepreneurial risk-taking can be informed and measured rather than reckless.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"During the storming stage, team members disagree about roles. What should a leader encourage?","options":["Constructive discussion and clarification of expectations","Permanent silence","Abandoning every shared goal","Ignoring all conflict"],"correct_index":0,"explanation":"Storming may involve conflict as members establish roles. Clarifying norms and responsibilities helps the team move towards more effective collaboration.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A presenter cannot answer a question confidently. What is the most professional response?","options":["Invent a statistic","Acknowledge the gap and offer to verify and follow up","Argue that questions are forbidden","Pretend the question was never asked"],"correct_index":1,"explanation":"Honesty protects credibility. Clarify the question and commit to checking reliable information rather than fabricating an answer.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A pilot product succeeds with ten loyal customers. Which expansion recommendation is most defensible?","options":["Launch nationally because ten loyal users prove universal demand.","Cancel the product because small pilots never help.","Test demand in a broader target-market sample and update the action plan before scaling.","Copy the pilot result into every future forecast unchanged."],"correct_index":2,"explanation":"A pilot provides useful but limited evidence. A broader relevant sample, cost estimates and milestones help judge whether the result will transfer to the intended market.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Action plans, presentations and team development. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","bst"],"metadata":{"term":3,"focus":"Action plans, presentations and team development","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"604aa7ab-91bf-59f9-8e04-5f989c3b2039","title":"Business Studies · Grade 11 · Term 4: Recruitment, selection and induction · Set A","subject":"Business Studies","grade":"Grade 11","questions":[{"question":"What is the main purpose of recruitment?","options":["Choose a candidate before defining the job","Dismiss all existing workers","Train every customer","Attract suitable applicants for a vacancy"],"correct_index":3,"explanation":"Recruitment creates a suitable applicant pool. Selection then evaluates applicants against job-related criteria.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which interview question is most appropriate for assessing a delivery planner?","options":["Describe how you would prioritise delayed deliveries","Which unrelated political party does your family support?","Why should we ignore your skills?","Will you accept unsafe work without questions?"],"correct_index":0,"explanation":"Job-relevant questions provide evidence of competence. Irrelevant or discriminatory questions do not fairly assess ability.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Why provide induction for a new employee?","options":["Avoid explaining the job","Explain the role, workplace procedures and safety expectations","Guarantee the employee never needs support","Replace all future communication"],"correct_index":1,"explanation":"Induction helps employees understand duties, colleagues, policies and safety. It is a starting point for ongoing support.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A worker earns R50 per hour for 20 hours. Before deductions, what is the pay?","options":["R70","R2.50","R1 000","R500"],"correct_index":2,"explanation":"Time-related pay = hourly rate×hours = 50×20=R1 000. This is gross pay before any deductions.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Two applicants have similar qualifications. An interviewer favours a friend without using job criteria. What is the best correction?","options":["Award the job privately to avoid paperwork.","Ask unrelated personal questions to justify the preference.","Use consistent job-related criteria, record evidence and manage the conflict of interest.","Treat friendship as proof of occupational competence."],"correct_index":2,"explanation":"Fair selection compares relevant evidence consistently and addresses conflicts of interest. Structured questions and documented scoring make the recommendation more defensible.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Recruitment, selection and induction. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","bst"],"metadata":{"term":4,"focus":"Recruitment, selection and induction","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=MA92xnIfEHk%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=zLnOddukw-4%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/bst-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"9c84e6d4-9582-58cd-a45f-0c020118a6fd","title":"Economics · Grade 11 · Term 2: Costs, revenue and elasticity · Set A","subject":"Economics","grade":"Grade 11","questions":[{"question":"A business sells 100 units at R20 each. Find total revenue.","options":["R120","R5","R2 000","R200"],"correct_index":2,"explanation":"Total revenue = price×quantity = 20×100=R2 000. Profit requires deducting costs, which are not provided here.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Total cost rises from R500 to R560 when output rises from 10 to 12 units. Find marginal cost per extra unit over this change.","options":["R60","R280","R50","R30"],"correct_index":3,"explanation":"Marginal cost = change in total cost/change in quantity = 60/2=R30 per unit for this interval.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Price rises by 10% and quantity demanded falls by 20%. Find the magnitude of price elasticity using these percentage changes.","options":["2","0.5","10","30"],"correct_index":0,"explanation":"Elasticity magnitude = 20/10=2, so demand is elastic. The signed ratio is negative, but the question explicitly asks for magnitude.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"If demand is price elastic, what usually happens to total revenue after a small price cut, other things equal?","options":["It must decrease","It increases","It stays zero","It becomes unrelated to quantity"],"correct_index":1,"explanation":"The percentage quantity increase exceeds the percentage price decrease, so total revenue increases within the elastic range.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A shop cuts price from R20 to R18 and sales rise from 100 to 120 units. Which revenue judgement is correct?","options":["Revenue falls because every price cut lowers revenue.","Revenue stays R2 000 because quantity does not affect it.","Revenue rises from R2 000 to R2 160, consistent with elastic demand over this change.","Revenue rises to R2 400 because the old price still applies."],"correct_index":2,"explanation":"Revenue is price times quantity: 20×100=2 000 and 18×120=2 160. The 20% quantity rise exceeds the 10% price fall using initial-value percentages.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Costs, revenue and elasticity. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","eco"],"metadata":{"term":2,"focus":"Costs, revenue and elasticity","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"b550db08-e456-5511-8773-77d32d35631b","title":"Economics · Grade 11 · Term 3: Growth, development and banking · Set A","subject":"Economics","grade":"Grade 11","questions":[{"question":"Which best distinguishes economic development from economic growth?","options":["They are always identical measures","Growth means only a higher population","Development excludes education and health","Development includes living conditions and structural improvements, beyond output growth"],"correct_index":3,"explanation":"Growth concerns increased real output. Development considers broader changes such as living standards, capabilities and economic structure.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why use real GDP instead of nominal GDP to compare output over time?","options":["It adjusts for price changes","It removes all population differences automatically","It measures happiness directly","It guarantees equal income"],"correct_index":0,"explanation":"Real GDP uses constant prices to help separate output changes from inflation. Per-capita measures additionally consider population.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which is a technical function of money?","options":["A guarantee of investment returns","Store of value","An unlimited natural resource","A replacement for every production input"],"correct_index":1,"explanation":"Money can serve as medium of exchange, unit of account and store of value. Inflation can reduce its purchasing power over time.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why do commercial banks assess borrowers before lending?","options":["To guarantee no loan can ever default","To remove the need for contracts","To evaluate repayment ability and credit risk","To lend every deposit to one person"],"correct_index":2,"explanation":"Credit assessment supports prudent lending and risk management, though it cannot eliminate defaults.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Nominal GDP rises 8% while the relevant price index rises 10%. Which claim needs correction?","options":["That price changes affect nominal comparisons.","That real GDP helps distinguish price and output changes.","That real output necessarily grew because nominal GDP increased.","That development includes more than GDP alone."],"correct_index":2,"explanation":"A nominal increase can be explained by higher prices. Under these indices the real factor is 1.08/1.10<1, suggesting a decline rather than proof of real growth.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Growth, development and banking. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","eco"],"metadata":{"term":3,"focus":"Growth, development and banking","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"39516408-42f5-53ca-bbad-d42152ba3b0e","title":"Economics · Grade 11 · Term 4: Globalisation and environmental sustainability · Set A","subject":"Economics","grade":"Grade 11","questions":[{"question":"Which change can promote globalisation?","options":["Lower communication and transport costs","Ending every form of international communication","Making all trade physically impossible","Removing every transport route"],"correct_index":0,"explanation":"Lower costs make cross-border trade, investment and communication easier. Effects differ across industries and households.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"What is a negative externality of factory air pollution?","options":["Only the factory's paid wage bill","A health cost borne by nearby residents that is not fully included in the factory's private costs","The firm's recorded profit","A benefit paid directly to every resident"],"correct_index":1,"explanation":"An external cost affects third parties outside the market transaction. Policy may seek to make decision-makers account for it.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"Which action supports sustainable resource use?","options":["Use every renewable resource faster than it regenerates","Treat pollution as having no cost","Harvest at a rate that allows replenishment while protecting ecosystems","Ignore future generations"],"correct_index":2,"explanation":"Sustainability considers current needs, ecosystem limits and future needs. Renewable does not mean unlimited at any rate of use.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why evaluate both benefits and costs of trade openness?","options":["Every person gains the same amount immediately","Trade has no effect on jobs","Only imports matter to an economy","Gains and adjustment costs can fall unevenly across groups"],"correct_index":3,"explanation":"Trade can support choice, specialisation and markets while creating adjustment pressures. Distribution and support policies matter.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A factory creates jobs but imposes unpriced health costs on neighbours. Which policy appraisal is strongest?","options":["Ignore health costs because they are outside the factory's accounts.","Close every factory without considering alternatives.","Compare employment benefits and external health costs, and assess measures that reduce pollution efficiently.","Treat all private costs as identical to all social costs."],"correct_index":2,"explanation":"A negative externality means some costs fall on third parties. A reasoned appraisal considers both benefits and social costs, including the effectiveness and consequences of corrective measures.","cognitive_level":{"code":"L3","label":"Synthesis and evaluation","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Globalisation and environmental sustainability. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","eco"],"metadata":{"term":4,"focus":"Globalisation and environmental sustainability","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=BjrxUz7iUNo%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=Lv-97xKN0eM%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/eco-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Synthesis and evaluation"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"cb45161d-0161-5075-aafe-c93be45d5a14","title":"Geography · Grade 11 · Term 2: Rock structure, slopes and mass movement · Set A","subject":"Geography","grade":"Grade 11","questions":[{"question":"A cuesta forms in strata with a gentle dip. Which slopes typically characterise it?","options":["Two identical vertical cliffs only","A flat surface with no slope","Only a volcanic crater","A steep scarp slope and a gentler dip slope"],"correct_index":3,"explanation":"Differential erosion of tilted resistant and less-resistant layers can produce an asymmetric ridge. The dip slope follows bedding inclination.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What is soil creep?","options":["Very slow downslope movement of soil","An explosive volcanic eruption","Water flowing uphill","Instant freezing of an ocean"],"correct_index":0,"explanation":"Soil creep is a slow mass movement under gravity. Bent trunks or tilted posts can provide evidence over time.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why can heavy rain increase landslide risk on a vulnerable slope?","options":["It always removes all gravity","Water can add weight and reduce material strength","It makes every slope stable","It removes every slope angle"],"correct_index":1,"explanation":"Saturation can increase load and pore pressure, reducing stability. Slope material, angle and vegetation affect the risk.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"On a topographic map, closely spaced contours generally indicate…","options":["A flat plain","A greater scale denominator by definition","A steep slope","A river flowing uphill"],"correct_index":2,"explanation":"For a constant contour interval, the same vertical change occurs over a shorter horizontal distance, indicating a steeper slope.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"A steep slope is cut for a road and later fails after heavy rain. Which explanation best integrates the evidence?","options":["Rainfall proves road cutting had no possible role.","Slope failure must be caused by one factor only.","Cutting may reduce support while rain increases saturation and reduces stability.","The road's painted line determines soil strength."],"correct_index":2,"explanation":"Slope instability can reflect interacting natural and human factors. Investigate geology, drainage, slope geometry and the timing of cutting and rainfall before assigning responsibility.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Rock structure, slopes and mass movement. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","geo"],"metadata":{"term":2,"focus":"Rock structure, slopes and mass movement","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"d15651aa-5e3d-55ab-b23b-d5053b8881b1","title":"Geography · Grade 11 · Term 3: Development, trade and aid · Set A","subject":"Geography","grade":"Grade 11","questions":[{"question":"Why use more than GDP per capita when comparing development?","options":["Development includes health, education and distribution as well as income","GDP per capita proves everyone earns the average","Income is never relevant","Only land area determines development"],"correct_index":0,"explanation":"Development is multidimensional. Combine income with social indicators and consider inequality and local context.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Which is an example of humanitarian aid?","options":["A routine export sale at market price","Emergency food and shelter after a disaster","A tax paid by a local shop","A share purchase by an investor"],"correct_index":1,"explanation":"Humanitarian aid addresses urgent needs and protects people in crises. Longer-term development assistance has different but sometimes connected aims.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"Why might reliance on one export commodity be risky?","options":["Its price can never change","Trade becomes completely independent of world markets","Global price changes can strongly affect income","It guarantees equal wealth"],"correct_index":2,"explanation":"Concentrated exports expose earnings to price and demand shocks. Diversification can reduce, though not eliminate, vulnerability.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What makes a development project more community-responsive?","options":["Outsiders assume every community has identical needs","The project never gathers feedback","Only publicity is measured","Local people help identify needs, decide priorities and evaluate outcomes"],"correct_index":3,"explanation":"Participation can improve relevance and accountability. Results should be evaluated with the people affected, not inferred from spending alone.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Two countries have equal GDP per capita, but different life expectancy and schooling. Which judgement is justified?","options":["All development measures must therefore be identical.","The country with less schooling necessarily has more income.","Equal average income does not establish equal development or distribution.","Health measures cannot inform development comparisons."],"correct_index":2,"explanation":"GDP per capita is an average economic indicator. Health, education, inequality and access can differ, so use several indicators before judging development.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Development, trade and aid. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","geo"],"metadata":{"term":3,"focus":"Development, trade and aid","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"bdc413aa-a55c-5aeb-86d6-a5b4987113b0","title":"Geography · Grade 11 · Term 4: Energy management and soil erosion · Set A","subject":"Geography","grade":"Grade 11","questions":[{"question":"Which energy source is renewable on a human timescale?","options":["Coal","Solar energy","Crude oil","Natural gas"],"correct_index":1,"explanation":"Sunlight is replenished continuously on human timescales. Fossil fuels form over geological timescales and are finite.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"What is a major environmental cost of coal-fired electricity?","options":["No emissions of any kind","Automatic restoration of mined land","Greenhouse gas emissions and air pollutants","Unlimited clean water production"],"correct_index":2,"explanation":"Coal combustion releases greenhouse gases and other pollutants. Full assessment also considers mining, water and management practices.","cognitive_level":{"code":"L1","label":"Knowledge and remembering","band":"lower"}},{"question":"How can overgrazing increase soil erosion?","options":["It always increases protective plant cover","It permanently stops rainfall","It eliminates all animal movement","It reduces vegetation cover, exposing soil to wind and runoff"],"correct_index":3,"explanation":"Loss of plant cover and roots leaves soil less protected. Grazing management should account for carrying capacity and recovery.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"Which action best supports household energy efficiency?","options":["Use efficient appliances and switch off unnecessary loads","Leave all heaters on in empty rooms","Treat electricity consumption as unmeasurable","Ignore insulation and maintenance"],"correct_index":0,"explanation":"Efficiency reduces energy needed for a service. Combine efficient equipment, maintenance and sensible use, then check actual consumption.","cognitive_level":{"code":"L2","label":"Understanding and applying","band":"middle"}},{"question":"An overgrazed hillside loses more soil than a vegetated one after storms. What investigation best tests vegetation's role?","options":["Compare unrelated slopes without measuring rainfall or soil.","Assume vegetation is the only possible cause.","Compare repeated soil-loss measurements on similar slopes with different cover, controlling other factors.","Use only a photograph taken before rain."],"correct_index":2,"explanation":"Similar slopes, soil and rainfall reduce competing explanations. Repeated measurements can reveal whether cover is associated with reduced runoff and erosion more reliably than a single observation.","cognitive_level":{"code":"L3","label":"Analysing and evaluating","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Energy management and soil erosion. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","geo"],"metadata":{"term":4,"focus":"Energy management and soil erosion","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=NRSYh-IvM_w%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20_%20GEOGRAPHY%20_%20GR%2010-12%20_%20WEB_C9A9.pdf?ver=2015-01-27-154144-177","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/geo-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and remembering","Understanding and applying","Analysing and evaluating"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"3a7d9526-866f-567e-bc4f-d31d5fadb75e","title":"History · Grade 11 · Term 2: Ideas of race and nationalisms · Set A","subject":"History","grade":"Grade 11","questions":[{"question":"Why are nineteenth-century racial hierarchies rejected by modern understandings of humanity?","options":["They are discriminatory social constructions, not a valid ranking of human worth or ability","They accurately rank every person's potential","They prove separate unequal human species","They require no scientific examination"],"correct_index":0,"explanation":"Historical racist ideas helped justify exclusion and violence. Modern evidence does not support ranking human populations by inherent worth or ability.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"What did eugenic policies attempt to do?","options":["Provide equal reproductive freedom to everyone","Control reproduction using discriminatory ideas about inherited human value","End every form of racism","Develop a neutral transport system"],"correct_index":1,"explanation":"Eugenics used harmful claims about heredity to justify coercion and exclusion. Explain and critique the ideas without endorsing them.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"What is nationalism in a historical context?","options":["Every form of friendship","A belief that all states must disappear immediately","Identification with a nation and claims linked to its political interests or self-determination","Only a preference for a sports team"],"correct_index":2,"explanation":"Nationalisms develop in particular contexts and can unite, exclude or challenge domination. Compare concrete movements rather than assuming all are identical.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why compare sources from different nationalist movements?","options":["To prove every movement had identical goals","To remove historical context","To assume one source speaks for all members","To examine similarities, differences and the circumstances shaping each"],"correct_index":3,"explanation":"Comparative work needs evidence about aims, leadership, membership and context, including tensions within movements.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"A nationalist pamphlet describes its own movement as representing the entire population. Which evaluation is best?","options":["Assume a pamphlet's claim proves universal representation.","Reject all nationalist sources without reading them.","Compare its aims and audience with evidence of support, exclusion and rival views.","Use modern popularity alone to establish past support."],"correct_index":2,"explanation":"Representation is a claim to investigate. The pamphlet reveals the movement's self-presentation, while other sources help assess who supported it and whose interests it excluded.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Ideas of race and nationalisms. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","hist"],"metadata":{"term":2,"focus":"Ideas of race and nationalisms","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"b9d8ea35-99df-5f91-8729-eece4ab695a8","title":"History · Grade 11 · Term 3: Segregation and the apartheid state · Set A","subject":"History","grade":"Grade 11","questions":[{"question":"What distinguishes apartheid as a state policy after 1948?","options":["The first appearance of any racism anywhere","A systematic extension and enforcement of racial segregation and unequal rights","Universal equal citizenship from its start","An immediate end to earlier segregation"],"correct_index":1,"explanation":"Apartheid built on earlier discriminatory structures while expanding and systematising them. A comparison should identify both continuity and change.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why did apartheid legislation affect everyday life?","options":["It applied only to foreign trade","It had no relation to state power","It regulated areas such as residence, movement, education and political participation","It guaranteed equal services to all"],"correct_index":2,"explanation":"Interlocking laws enforced racial control across many parts of life. Specific examples strengthen an explanation of impact.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What is a limitation of using a government statement alone to assess a policy's effects?","options":["Government documents contain no historical information","It must describe every outcome accurately","It removes the need for other evidence","It may present official justification while omitting affected people's experiences"],"correct_index":3,"explanation":"Official sources reveal intentions and public messaging. Compare them with implementation records and affected communities' testimony.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Why is a single-cause explanation of the 1948 election result weak?","options":["It may ignore interacting political, social and electoral factors","Every historical event has exactly one cause","Only election dates matter","Evidence is unnecessary for elections"],"correct_index":0,"explanation":"Historical explanation should weigh several relevant factors and distinguish background conditions from immediate events.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"A government statement says a segregation policy benefits everyone. Testimony from affected families describes restrictions. What should a historian do?","options":["Accept official status as proof that family accounts are false.","Assume disagreement makes both sources worthless.","Compare purpose, context and specific evidence, explaining differing perspectives.","Choose whichever source has the shorter text."],"correct_index":2,"explanation":"Different positions shape accounts, but claims can still be investigated. Explain each source's perspective and compare its evidence with legislation and further testimony.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Segregation and the apartheid state. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","hist"],"metadata":{"term":3,"focus":"Segregation and the apartheid state","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"d3213c0a-63a1-51c4-820c-e8ae8fe12a94","title":"History · Grade 11 · Term 4: Resistance, repression and source skills · Set A","subject":"History","grade":"Grade 11","questions":[{"question":"What did mass mobilisation seek to achieve in resistance to apartheid?","options":["Limit action to a single secret diary","Remove all public participation","Bring many people into collective political action","Guarantee immediate victory without risk"],"correct_index":2,"explanation":"Mobilisation organised collective action through campaigns and networks. Its forms and effectiveness changed in response to conditions and repression.","cognitive_level":{"code":"L1","label":"Historical knowledge and evidence retrieval","band":"lower"}},{"question":"Why was the Sharpeville massacre in 1960 historically significant?","options":["It ended apartheid that day","It occurred after the 1994 election","It had no wider consequences","It intensified criticism of apartheid and affected the course of resistance and state repression"],"correct_index":3,"explanation":"The killing of protesters had major national and international repercussions. Explain the consequences with evidence and correct chronology.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"What was a consequence of the Rivonia Trial for the liberation movement?","options":["Key leaders were imprisoned, affecting leadership and resistance strategies","Every political organisation became freely legal","Apartheid ended immediately","All international opposition disappeared"],"correct_index":0,"explanation":"The trial and imprisonment of leaders reshaped the struggle. It did not end resistance, which continued through different organisations and settings.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"When two sources disagree, what should a learner do?","options":["Assume both are worthless","Examine perspective, date, evidence and context before judging the claims","Choose the shorter source automatically","Treat the older source as always correct"],"correct_index":1,"explanation":"Contradiction is a reason for investigation. Evaluate what each source can establish and seek additional corroborating evidence.","cognitive_level":{"code":"L2","label":"Concepts and straightforward interpretation","band":"middle"}},{"question":"Two sources give different accounts of a protest. Which approach produces the strongest source-based answer?","options":["Average every number without checking how it was obtained.","Select the later source solely because it is later.","Identify precise agreements and differences, examine provenance and corroborate key claims.","Avoid all conclusions because disagreement exists."],"correct_index":2,"explanation":"Source disagreement is evidence to analyse. Dates, access to events, purposes and corroboration help judge particular claims rather than automatically accepting or rejecting a whole source.","cognitive_level":{"code":"L3","label":"Evaluate evidence and perspectives","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Resistance, repression and source skills. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","hist"],"metadata":{"term":4,"focus":"Resistance, repression and source skills","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=RtCxM8k_XeI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/Portals/0/CD/National%20Curriculum%20Statements%20and%20Vocational/CAPS%20FET%20%20HISTORY%20GR%2010-12%20%20WeB.pdf","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/hist-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS-informed historical knowledge and source skills","cognitive_levels":["Historical knowledge and evidence retrieval","Concepts and straightforward interpretation","Evaluate evidence and perspectives"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"280d8489-f236-5c67-8f85-0157eabdbcf8","title":"Tourism · Grade 11 · Term 2: Car rental, heritage and marketing · Set A","subject":"Tourism","grade":"Grade 11","questions":[{"question":"Why should a traveller compare the full car-rental quote rather than only the daily rate?","options":["Every quote includes unlimited free extras","Extra charges, insurance terms and mileage conditions affect total cost","The daily rate is always the final cost","Contract conditions never matter"],"correct_index":1,"explanation":"Check included kilometres, excesses, optional extras and other charges. A low headline rate may not be the cheapest suitable option.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What does an insurance excess generally mean in a rental context?","options":["A guaranteed refund of the whole rental","A free extra driver in every contract","The amount the renter may remain liable for under the cover's terms","An unlimited fuel allowance"],"correct_index":2,"explanation":"An excess is a potential retained liability. Read exclusions, reductions and conditions rather than assuming the renter has no risk.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A museum promotes a community-led exhibition. What should its marketing emphasise?","options":["Invented ceremonies to attract attention","A guarantee that all visitors share one culture","Photographs without considering permissions","Accurate information and respectful representation of the community"],"correct_index":3,"explanation":"Cultural tourism needs accurate, respectful interpretation and appropriate permissions. Community participation strengthens authenticity and relevance.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Which is a target-market decision?","options":["Designing a short affordable itinerary for local families","Buying fuel for every vehicle","Ignoring visitor research","Offering every product at an identical price by law"],"correct_index":0,"explanation":"Market selection informs product, price and promotion decisions. It starts with understanding the needs of a defined visitor group.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Rental A costs R400/day plus R300 once; B costs R500/day with that fee included. For two days, excluding all other costs, which quote is cheaper?","options":["A at R800, ignoring its fee.","Both cost R1 000.","B at R1 000, compared with A at R1 100.","B at R500 for the entire two-day hire."],"correct_index":2,"explanation":"A totals 2×400+300=R1 100. B totals 2×500=R1 000. Compare the complete stated cost, then check mileage, cover and other terms before an actual booking.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Car rental, heritage and marketing. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-2","formative","tour"],"metadata":{"term":2,"focus":"Car rental, heritage and marketing","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"543b75af-65ff-57d7-8b29-e1f717c60c36","title":"Tourism · Grade 11 · Term 3: Itineraries, exchange rates and service · Set A","subject":"Tourism","grade":"Grade 11","questions":[{"question":"An itinerary has activities at 09:00 and 09:15 in towns 80 km apart. What is its main problem?","options":["The font must be changed before anything else","Every route must cross a border","Travel time is unrealistic","It has too few currencies"],"correct_index":2,"explanation":"An itinerary must allow realistic travel and visiting time, plus breaks and contingencies. Geographic sequence and timing should work together.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A bank sells foreign currency at R20 per US dollar. Ignoring fees, how many dollars does R2 000 buy?","options":["US$40 000","US$1 980","US$20","US$100"],"correct_index":3,"explanation":"Divide rand by rand per dollar: 2 000/20=100 dollars. Fees and the appropriate buying or selling rate affect real transactions.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A tourist exchanges US$50 at R18 per dollar, with no fee. How many rand do they receive?","options":["R900","R2.78","R68","R90"],"correct_index":0,"explanation":"Multiply dollars by rand per dollar: 50×18=R900. Track the units to choose multiplication or division.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A foreign guest struggles to understand a service explanation. What should staff do?","options":["Speak louder and refuse to clarify","Use clear language, check understanding and offer suitable support","Mock the guest's language","Assume agreement means understanding"],"correct_index":1,"explanation":"Respectful communication adapts language and checks the message was understood. Avoid stereotyping or treating language difficulty as lack of ability.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A visit ends at 10:00; the next begins at 10:30, 60 km away. Driving averages 60 km/h before parking time. What change is needed?","options":["Keep the plan because 60 km can always be driven in 30 minutes.","Delete the distance rather than revise the times.","Allow at least an hour of driving plus a practical arrival buffer.","Assume parking takes negative time."],"correct_index":2,"explanation":"At 60 km/h, 60 km requires one hour before parking or delays. The half-hour gap is infeasible; adjust the itinerary and include appropriate buffers.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Itineraries, exchange rates and service. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-3","formative","tour"],"metadata":{"term":3,"focus":"Itineraries, exchange rates and service","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}},{"id":"0d68f508-8359-5c01-8458-2dcd9b6455ab","title":"Tourism · Grade 11 · Term 4: Tourism careers and sustainable enterprise · Set A","subject":"Tourism","grade":"Grade 11","questions":[{"question":"Which skill is especially valuable for a tour-planning entrepreneur?","options":["Ignoring budgets","Promising every attraction is always open","Copying private customer data without permission","Researching customer needs and building workable costed itineraries"],"correct_index":3,"explanation":"A viable product needs customer research, realistic logistics, pricing and responsible information handling.","cognitive_level":{"code":"L1","label":"Knowledge and comprehension","band":"lower"}},{"question":"Why can tourism businesses benefit from reducing wasted water?","options":["It lowers avoidable resource use and can reduce costs","It guarantees no future drought","It removes the need for hygiene","It means guests never need drinking water"],"correct_index":0,"explanation":"Efficiency and conservation support resilience and sustainability. Maintain hygiene and essential services while reducing waste.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"What does a carbon footprint estimate?","options":["Only the size of a person's shoes","Greenhouse gas emissions associated with an activity, usually expressed as CO₂ equivalent","The number of trees in a brochure","A guarantee that an activity has no impact"],"correct_index":1,"explanation":"A footprint helps identify major emission sources and assess reductions. It depends on boundaries and calculation assumptions.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A community starts a guided walking tour. What most supports responsible growth?","options":["Excluding local voices from all decisions","Ignoring carrying capacity","Fair local participation, safety planning and protection of places visited","Inventing local history for sales"],"correct_index":2,"explanation":"Responsible enterprise balances economic opportunity with community rights, safety and environmental and cultural care.","cognitive_level":{"code":"L2","label":"Application and analysis","band":"middle"}},{"question":"A walking-tour project doubles visitor numbers while residents report crowding and damage. Which growth plan is strongest?","options":["Double visitors again because numbers alone define success.","Ignore residents because tourists are the only stakeholders.","Review carrying capacity, resident feedback and site protection alongside income.","Stop recording damage to improve the statistics."],"correct_index":2,"explanation":"Responsible enterprise evaluates visitor benefits with local wellbeing and conservation. Limits, scheduling and community input can protect the asset on which long-term tourism depends.","cognitive_level":{"code":"L3","label":"Evaluation and synthesis","band":"higher"}}],"created_by":"SmartBridge FET content team","is_published":true,"description":"Short formative practice: Tourism careers and sustainable enterprise. Selected CAPS/ATP skills, with explanations. Not a complete term assessment.","quiz_type":"practice","difficulty_level":"medium","time_limit_minutes":12,"passing_score_percentage":50,"total_questions":5,"allow_retakes":true,"show_answers_after_submission":true,"tags":["CAPS","ATP","term-4","formative","tour"],"metadata":{"term":4,"focus":"Tourism careers and sustainable enterprise","language":"en","content_version":"2026-10-21.2","content_origin":"SmartBridge original","curriculum_year":2026,"atp_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=A7H7BQvcivI%3d&tabid=3205&portalid=0&mid=10752","caps_url":"https://www.education.gov.za/LinkClick.aspx?fileticket=QCDkiagAGeI%3d&tabid=570&portalid=0&mid=1558","retention_circular_url":"https://www.education.gov.za/Portals/0/Documents/Publications/2026/Circulars/Circular%20S19%20of%202025%20and%20Annexures.pdf","verified_on":"2026-10-21","lesson_path":"/study-packs/tour-11","coverage":"Selected topic and skill samples; not exhaustive term coverage or a full examination paper.","moderation_status":"Independent teacher and language moderation pending","term_note":"Revision included where specified by ATP; some Grade 10/11 Term 4 plans introduce new content.","set_id":"A","set_label":"Term-focused practice","cognitive_framework":"CAPS subject taxonomy","cognitive_levels":["Knowledge and comprehension","Application and analysis","Evaluation and synthesis"],"classification_status":"Draft author classification; independent moderation pending","assessment_note":"Five-question formative samples do not reproduce formal examination mark weightings or assess extended written responses."}}]$smartbridge$::jsonb)
